content:
:root {
  --color-primary: #2563eb;
  --color-primary-hover: #1d4ed8;
  --color-primary-light: #eff6ff;
  --color-primary-border: #bfdbfe;
  --color-success: #16a34a;
  --color-success-bg: #f0fdf4;
  --color-danger: #dc2626;
  --color-danger-bg: #fef2f2;
  --color-text-main: #0f172a;
  --color-text-sub: #475569;
  --color-text-muted: #94a3b8;
  --color-bg-base: #f8fafc;
  --color-bg-card: #ffffff;
  --color-border: #e2e8f0;
  --color-border-focus: #3b82f6;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.03);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --transition: all 0.2s ease-in-out;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Yu Gothic", sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg-base);
  color: var(--color-text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* ダッシュボード全体コンテナ */
.dashboard-container {
  max-width: 1240px;
  margin: 0 auto;
  padding: 24px 20px 48px;
  display: flex;
  flex-direction: column;
  gap: 28px;
}

/* ヘッダー */
.dashboard-header {
  display: flex;
  flex-direction: column;
  gap: 16px;
  background: var(--color-bg-card);
  padding: 24px 28px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
}

@media (min-width: 768px) {
  .dashboard-header {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.header-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: -0.02em;
}

.header-subtitle {
  font-size: 0.875rem;
  color: var(--color-text-sub);
  margin-top: 4px;
}

.header-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}

/* ボタン */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 0.875rem;
  font-weight: 500;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: var(--transition);
  border: 1px solid transparent;
  outline: none;
  white-space: nowrap;
  user-select: none;
}

.btn:focus-visible {
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.3);
}

.btn-primary {
  background-color: var(--color-primary);
  color: #ffffff;
  border-color: var(--color-primary);
}

.btn-primary:hover {
  background-color: var(--color-primary-hover);
  border-color: var(--color-primary-hover);
}

.btn-primary:active {
  transform: translateY(1px);
}

.btn-outline {
  background-color: var(--color-bg-card);
  color: var(--color-text-sub);
  border-color: var(--color-border);
}

.btn-outline:hover {
  background-color: var(--color-bg-base);
  color: var(--color-text-main);
  border-color: #cbd5e1;
}

.btn-outline:active {
  transform: translateY(1px);
}

.btn-sm {
  font-size: 0.75rem;
  padding: 6px 12px;
}

/* KPIカードグリッド */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: 16px;
}

@media (min-width: 540px) {
  .kpi-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 960px) {
  .kpi-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.kpi-card {
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

.kpi-card:hover {
  border-color: #cbd5e1;
  box-shadow: var(--shadow-md);
}

.kpi-card-highlight {
  background: linear-gradient(135deg, #ffffff 0%, var(--color-primary-light) 100%);
  border-color: var(--color-primary-border);
}

.kpi-label {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-text-sub);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.kpi-value {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.kpi-subtext {
  font-size: 0.75rem;
  color: var(--color-text-muted);
  display: flex;
  align-items: center;
  gap: 4px;
}

/* グラフセクション */
.chart-section {
  width: 100%;
}

.chart-card {
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
}

.chart-header {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

@media (min-width: 640px) {
  .chart-header {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.chart-title {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-text-main);
}

.chart-legend {
  display: flex;
  align-items: center;
  gap: 16px;
  font-size: 0.8125rem;
  color: var(--color-text-sub);
}

.chart-wrapper {
  width: 100%;
  height: 380px;
  min-height: 320px;
}

/* グラフカスタムツールチップ */
.custom-tooltip {
  background-color: rgba(15, 23, 42, 0.92);
  backdrop-filter: blur(4px);
  color: #ffffff;
  padding: 12px 16px;
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-lg);
  font-size: 0.8125rem;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.tooltip-month {
  font-weight: 700;
  font-size: 0.875rem;
  margin-bottom: 6px;
  padding-bottom: 4px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.2);
  color: #f8fafc;
}

.tooltip-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  margin: 3px 0;
}

.tooltip-label {
  color: #cbd5e1;
}

.tooltip-value {
  font-weight: 600;
  font-feature-settings: "tnum";
}

/* データテーブルセクション */
.table-section {
  width: 100%;
}

.table-card {
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
}

.table-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.table-title {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-text-main);
}

.table-wrapper {
  width: 100%;
  overflow-x: auto;
  border-radius: var(--radius-sm);
  border: 1px solid var(--color-border);
}

.sales-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.875rem;
}

.sales-table th {
  background-color: var(--color-bg-base);
  color: var(--color-text-sub);
  font-weight: 600;
  padding: 12px 16px;
  border-bottom: 1px solid var(--color-border);
  white-space: nowrap;
}

.sales-table td {
  padding: 10px 16px;
  border-bottom: 1px solid var(--color-border);
  vertical-align: middle;
}

.sales-table tr:last-child td {
  border-bottom: none;
}

.sales-table tr:hover td {
  background-color: rgba(241, 245, 249, 0.6);
}

.month-cell {
  font-weight: 600;
  color: var(--color-text-main);
  white-space: nowrap;
}

.input-cell {
  width: 180px;
}

.sales-input {
  width: 100%;
  max-width: 140px;
  padding: 6px 10px;
  font-size: 0.875rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background-color: #ffffff;
  color: var(--color-text-main);
  text-align: right;
  font-feature-settings: "tnum";
  transition: var(--transition);
}

.sales-input:focus {
  outline: none;
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

/* 差分ハイライト */
.diff-positive {
  color: var(--color-success);
  background-color: var(--color-success-bg);
  padding: 4px 8px;
  border-radius: 4px;
  font-weight: 600;
  font-size: 0.8125rem;
  display: inline-block;
  font-feature-settings: "tnum";
}

.diff-negative {
  color: var(--color-danger);
  background-color: var(--color-danger-bg);
  padding: 4px 8px;
  border-radius: 4px;
  font-weight: 600;
  font-size: 0.8125rem;
  display: inline-block;
  font-feature-settings: "tnum";
}

export interface MonthlySales {
  month: string;
  sales: number;
  target: number;
}

export interface SalesSummaryData {
  total: number;
  average: number;
  maxMonth: string;
  maxValue: number;
  minMonth: string;
  minValue: number;
  achievementRate: number;
}

export interface SalesChartProps {
  data: MonthlySales[];
  showTarget: boolean;
}

export interface SalesTableProps {
  data: MonthlySales[];
  onUpdateSales: (monthIndex: number, newSales: number) => void;
}

export interface SalesSummaryProps {
  summary: SalesSummaryData;
}

import { FC } from 'react';
import { SalesSummaryProps } from '../types';

const SalesSummary: FC<SalesSummaryProps> = ({ summary }) => {
  const formatYen = (val: number): string => {
    return Math.round(val).toLocaleString('ja-JP');
  };

  return (
    <div className="kpi-grid">
      <div className="kpi-card kpi-card-highlight">
        <span className="kpi-label">年間総売上</span>
        <span className="kpi-value">{formatYen(summary.total)} <span style={{ fontSize: '1rem', fontWeight: 500 }}>万円</span></span>
        <span className="kpi-subtext">1月〜12月合計実績</span>
      </div>

      <div className="kpi-card">
        <span className="kpi-label">月平均売上</span>
        <span className="kpi-value">{formatYen(summary.average)} <span style={{ fontSize: '1rem', fontWeight: 500 }}>万円</span></span>
        <span className="kpi-subtext">月間平均実績</span>
      </div>

      <div className="kpi-card">
        <span className="kpi-label">年間目標達成率</span>
        <span className="kpi-value">{summary.achievementRate.toFixed(1)} <span style={{ fontSize: '1rem', fontWeight: 500 }}>%</span></span>
        <span className="kpi-subtext">目標対比パフォーマンス</span>
      </div>

      <div className="kpi-card">
        <span className="kpi-label">最高 / 最低売上月</span>
        <span className="kpi-value" style={{ fontSize: '1.25rem', paddingTop: '4px' }}>
          {summary.maxMonth} ({formatYen(summary.maxValue)}万)
        </span>
        <span className="kpi-subtext">
          最低: {summary.minMonth} ({formatYen(summary.minValue)}万円)
        </span>
      </div>
    </div>
  );
};

export default SalesSummary;

import { FC } from 'react';
import {
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  TooltipProps
} from 'recharts';
import { SalesChartProps, MonthlySales } from '../types';

interface CustomTooltipProps extends TooltipProps<number, string> {
  active?: boolean;
  payload?: Array<{
    name: string;
    value: number;
    color: string;
    dataKey: string;
    payload: MonthlySales;
  }>;
  label?: string;
}

const CustomChartTooltip: FC<CustomTooltipProps> = ({ active, payload, label }) => {
  if (active && payload && payload.length) {
    const currentData = payload[0].payload;
    const diff = currentData.sales - currentData.target;
    return (
      <div className="custom-tooltip">
        <div className="tooltip-month">{label}の売上詳細</div>
        <div className="tooltip-row">
          <span className="tooltip-label">売上実績:</span>
          <span className="tooltip-value">{currentData.sales.toLocaleString('ja-JP')} 万円</span>
        </div>
        <div className="tooltip-row">
          <span className="tooltip-label">目標売上:</span>
          <span className="tooltip-value">{currentData.target.toLocaleString('ja-JP')} 万円</span>
        </div>
        <div className="tooltip-row">
          <span className="tooltip-label">差額:</span>
          <span
            className="tooltip-value"
            style={{ color: diff >= 0 ? '#4ade80' : '#f87171' }}
          >
            {diff >= 0 ? `+${diff.toLocaleString('ja-JP')}` : diff.toLocaleString('ja-JP')} 万円
          </span>
        </div>
      </div>
    );
  }
  return null;
};

const SalesChart: FC<SalesChartProps> = ({ data = [], showTarget = true }) => {
  return (
    <div className="chart-card">
      <div className="chart-header">
        <h2 className="chart-title">月別売上パフォーマンス推移</h2>
      </div>

      <div className="chart-wrapper">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart
            data={data}
            margin={{ top: 20, right: 20, left: 10, bottom: 10 }}
          >
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
            <XAxis
              dataKey="month"
              tickLine={false}
              axisLine={{ stroke: '#cbd5e1' }}
              tick={{ fill: '#475569', fontSize: 12 }}
            />
            <YAxis
              tickLine={false}
              axisLine={false}
              tick={{ fill: '#475569', fontSize: 12 }}
              tickFormatter={(value) => `${value}万`}
            />
            <Tooltip content={<CustomChartTooltip />} />
            <Legend
              wrapperStyle={{ paddingTop: 16 }}
              formatter={(value) => (value === 'sales' ? '売上実績（万円）' : '目標売上（万円）')}
            />
            <Bar
              dataKey="sales"
              name="sales"
              fill="#2563eb"
              radius={[4, 4, 0, 0]}
              maxBarSize={48}
            />
            {showTarget && (
              <Bar
                dataKey="target"
                name="target"
                fill="#94a3b8"
                radius={[4, 4, 0, 0]}
                maxBarSize={48}
              />
            )}
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default SalesChart;

import { FC, ChangeEvent } from 'react';
import { SalesTableProps } from '../types';

const SalesTable: FC<SalesTableProps> = ({ data = [], onUpdateSales }) => {
  const handleInputChange = (index: number, e: ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value.replace(/[^0-9]/g, '');
    const numValue = rawValue === '' ? 0 : Math.max(0, parseInt(rawValue, 10));
    onUpdateSales?.(index, numValue);
  };

  return (
    <div className="table-card">
      <div className="table-header">
        <h2 className="table-title">月別売上実績データ入力・詳細一覧</h2>
      </div>

      <div className="table-wrapper">
        <table className="sales-table">
          <thead>
            <tr>
              <th>対象月</th>
              <th>売上実績 (万円)</th>
              <th>目標金額 (万円)</th>
              <th>目標差額</th>
              <th>達成率</th>
            </tr>
          </thead>
          <tbody>
            {data.map((item, index) => {
              const diff = item.sales - item.target;
              const rate = item.target > 0 ? (item.sales / item.target) * 100 : 0;
              const isPositive = diff >= 0;

              return (
                <tr key={item.month}>
                  <td className="month-cell">{item.month}</td>
                  <td className="input-cell">
                    <input
                      type="number"
                      className="sales-input"
                      value={item.sales || ''}
                      onChange={(e) => handleInputChange(index, e)}
                      min={0}
                      step={10}
                      aria-label={`${item.month}の売上`}
                    />
                  </td>
                  <td>{item.target.toLocaleString('ja-JP')} 万円</td>
                  <td>
                    <span className={isPositive ? 'diff-positive' : 'diff-negative'}>
                      {isPositive ? `+${diff.toLocaleString('ja-JP')}` : diff.toLocaleString('ja-JP')} 万円
                    </span>
                  </td>
                  <td style={{ fontWeight: 600 }}>
                    {rate.toFixed(1)}%
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default SalesTable;

import { useState, useMemo, FC } from 'react';
import { MonthlySales, SalesSummaryData } from './types';
import SalesSummary from './components/SalesSummary';
import SalesChart from './components/SalesChart';
import SalesTable from './components/SalesTable';

const INITIAL_SALES_DATA: MonthlySales[] = [
  { month: '1月', sales: 420, target: 400 },
  { month: '2月', sales: 380, target: 400 },
  { month: '3月', sales: 560, target: 500 },
  { month: '4月', sales: 490, target: 450 },
  { month: '5月', sales: 510, target: 480 },
  { month: '6月', sales: 620, target: 550 },
  { month: '7月', sales: 580, target: 550 },
  { month: '8月', sales: 530, target: 500 },
  { month: '9月', sales: 610, target: 580 },
  { month: '10月', sales: 640, target: 600 },
  { month: '11月', sales: 690, target: 620 },
  { month: '12月', sales: 850, target: 750 },
];

const HIGH_PERFORMANCE_DATA: MonthlySales[] = [
  { month: '1月', sales: 520, target: 400 },
  { month: '2月', sales: 490, target: 400 },
  { month: '3月', sales: 680, target: 500 },
  { month: '4月', sales: 590, target: 450 },
  { month: '5月', sales: 630, target: 480 },
  { month: '6月', sales: 750, target: 550 },
  { month: '7月', sales: 710, target: 550 },
  { month: '8月', sales: 650, target: 500 },
  { month: '9月', sales: 720, target: 580 },
  { month: '10月', sales: 780, target: 600 },
  { month: '11月', sales: 830, target: 620 },
  { month: '12月', sales: 980, target: 750 },
];

const TARGET_ONLY_DATA: MonthlySales[] = [
  { month: '1月', sales: 400, target: 400 },
  { month: '2月', sales: 400, target: 400 },
  { month: '3月', sales: 500, target: 500 },
  { month: '4月', sales: 450, target: 450 },
  { month: '5月', sales: 480, target: 480 },
  { month: '6月', sales: 550, target: 550 },
  { month: '7月', sales: 550, target: 550 },
  { month: '8月', sales: 500, target: 500 },
  { month: '9月', sales: 580, target: 580 },
  { month: '10月', sales: 600, target: 600 },
  { month: '11月', sales: 620, target: 620 },
  { month: '12月', sales: 750, target: 750 },
];

const App: FC = () => {
  const [salesData, setSalesData] = useState<MonthlySales[]>(INITIAL_SALES_DATA);
  const [showTarget, setShowTarget] = useState<boolean>(true);

  const handleUpdateSales = (monthIndex: number, newSales: number) => {
    setSalesData((prev) => {
      const next = [...prev];
      if (next[monthIndex]) {
        next[monthIndex] = { ...next[monthIndex], sales: newSales };
      }
      return next;
    });
  };

  const summary = useMemo<SalesSummaryData>(() => {
    if (!salesData.length) {
      return {
        total: 0,
        average: 0,
        maxMonth: '-',
        maxValue: 0,
        minMonth: '-',
        minValue: 0,
        achievementRate: 0,
      };
    }

    let total = 0;
    let targetTotal = 0;
    let max = salesData[0];
    let min = salesData[0];

    salesData.forEach((item) => {
      total += item.sales;
      targetTotal += item.target;
      if (item.sales > max.sales) {
        max = item;
      }
      if (item.sales < min.sales) {
        min = item;
      }
    });

    const average = total / salesData.length;
    const achievementRate = targetTotal > 0 ? (total / targetTotal) * 100 : 0;

    return {
      total,
      average,
      maxMonth: max.month,
      maxValue: max.sales,
      minMonth: min.month,
      minValue: min.sales,
      achievementRate,
    };
  }, [salesData]);

  const handleApplyPreset = (preset: 'standard' | 'high' | 'reset') => {
    if (preset === 'standard') {
      setSalesData(INITIAL_SALES_DATA);
    } else if (preset === 'high') {
      setSalesData(HIGH_PERFORMANCE_DATA);
    } else if (preset === 'reset') {
      setSalesData(TARGET_ONLY_DATA);
    }
  };

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <div>
          <h1 className="header-title">年間売上データ分析ダッシュボード</h1>
          <p className="header-subtitle">1月〜12月の売上実績・目標対比の可視化と動的シミュレーション</p>
        </div>
        <div className="header-controls">
          <button
            type="button"
            className="btn btn-outline btn-sm"
            onClick={() => handleApplyPreset('standard')}
          >
            標準実績
          </button>
          <button
            type="button"
            className="btn btn-outline btn-sm"
            onClick={() => handleApplyPreset('high')}
          >
            好調年度
          </button>
          <button
            type="button"
            className="btn btn-outline btn-sm"
            onClick={() => handleApplyPreset('reset')}
          >
            計画値リセット
          </button>
          <button
            type="button"
            className={showTarget ? 'btn btn-primary btn-sm' : 'btn btn-outline btn-sm'}
            onClick={() => setShowTarget(!showTarget)}
          >
            {showTarget ? '目標売上: 表示中' : '目標売上: 非表示'}
          </button>
        </div>
      </header>

      <SalesSummary summary={summary} />

      <section className="chart-section">
        <SalesChart data={salesData} showTarget={showTarget} />
      </section>

      <section className="table-section">
        <SalesTable data={salesData} onUpdateSales={handleUpdateSales} />
      </section>
    </div>
  );
};

export default App;
